<span class="line">pg_losses2 <span class="token operator">=</span> <span class="token operator">-</span>advantages <span class="token operator">*</span> torch<span class="token punctuation">.</span>clamp<span class="token punctuation">(</span>ratio<span class="token punctuation">,</span> <span class="token number">1.0</span> <span class="token operator">-</span> cliprange<span class="token punctuation">,</span> <span class="token number">1.0</span> <span class="token operator">+</span> cliprange<span class="token punctuation">)</span></span>
